{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Verapamil, the closest retrieved analogue, showed 27% absolute oral bioavailability in healthy volunteers after an 80 mg oral dose versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Norverapamil, the N-demethylated verapamil analogue, had 34 ± 12% oral bioavailability versus IV in healthy men, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Bevantolol, which shares the 3,4-dimethoxyphenethylamine moiety, showed a mean absolute oral bioavailability of 57% (range 26–98%) in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C79"],
      "claim": "Sulpiride, a sulfonyl-containing drug with P-gp-related absorption limitations, still achieved 35% absolute oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Venlafaxine, a dimethoxyphenyl/tertiary amine analogue, had 44% absolute oral bioavailability in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One verapamil study in patients reported 12% bioavailability, providing contradictory low-F evidence, but this is an outlier relative to the majority of verapamil absolute bioavailability measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, led by the closest analogue verapamil (F ≈ 20–33%) and supported by norverapamil, bevantolol, sulpiride, and venlafaxine, indicates that the query's oral bioavailability is ≥ 20%. The few sub-20% verapamil values are outliers and do not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The effect of the cyclic disulfone moiety on intestinal permeability and first-pass metabolism is not directly captured by any evidence molecule.",
    "Verapamil's bioavailability is borderline (~20%) and variable, introducing uncertainty in extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

